# Shared by lessons 3 and 4: a clickable formula sheet, and the interim "what we learned" stop.


def FSHEET(groups, hint='לחצו על כל נוסחה: מה היא אומרת, דוגמה במספרים, ואיך כותבים אותה באקסל.'):
    """A formula sheet in groups. Each formula is a button: a click shows its meaning, a numeric example and the Excel way.
    groups: (reveal step, title, colour class, [(label, formula, meaning, example, excel)])."""
    if MODE == 'pdf':
        out = ''
        for n, title, cls, items in groups:
            out += f'<h4>{TX(title)}</h4><table class="tbl2"><tr><th>מה</th><th>נוסחה</th><th>משמעות ודוגמה</th><th>באקסל</th></tr>'
            out += ''.join(f'<tr><td>{TX(l)}</td><td>{TX(f)}</td><td>{TX(w)} {TX(e)}</td><td>{TX(x)}</td></tr>' for l, f, w, e, x in items) + '</table>'
        return out
    g, d, k = '', '', 0
    for n, title, cls, items in groups:
        chips = ''
        for l, f, w, e, x in items:
            k += 1
            chips += f'<button class="xp-c" data-i="{k}"><span>{TX(l)}</span><em>{TX(f)}</em></button>'
            d += (f'<div class="xp-x" data-i="{k}" hidden><b class="xp-h">{TX(l)}</b><div class="xp-f">{TX(f)}</div><p>{TX(w)}</p>'
                  f'<div class="xp-e"><b>דוגמה:</b> {TX(e)}</div><div class="xp-l"><b>באקסל:</b> {TX(x)}</div></div>')
        g += ST(n, f'<b class="xp-t">{TX(title)}</b><div class="xp-cs">{chips}</div>', cls='xp-grp ' + cls)
    return f'<div class="xp"><div class="xp-g">{g}</div><div class="xp-d"><div class="xp-0">👆 {TX(hint)}</div>{d}</div></div>'


def STOPX(n, items, face, top, bot, title=None):
    """Interim stop: what we learned in this part, in plain words, one line per click."""
    S(f's-stop{n}', f'מה למדנו: חלק {n}', title or f'עצירה: מה למדנו בחלק {n}, במילים פשוטות',
      '<div class="row top stp-r"><div class="stp">' + ''.join(ST(i + 1, f'<b>{i + 1}</b><span>{TX(x)}</span>', cls='si') for i, x in enumerate(items)) + '</div>'
      + MEME(face, top, bot, len(items) + 1) + '</div>', kick=f'חלק {n} · עצירת ביניים', cls='pfs')


def KEYS(sid, n, title, h, cards, tail=None):
    """Before the exercises of a part: the formula, the Excel way and the trap, one card per click."""
    lab = [('📐', 'הנוסחה'), ('⌨️', 'איך באקסל'), ('⚠️', 'המלכודת')]
    if MODE == 'pdf':
        S(sid, title, h, ''.join(f'<p><b>{lab[i][1]}.</b></p>{c}' for i, c in enumerate(cards)) + ('<p><b>בחלק הזה:</b> ' + ' · '.join(f'רמה {k}: {TX(t)}' for k, t in tail) + '</p>' if tail else ''))
        return
    body = '<div class="kc">' + ''.join(ST(i + 1, f'<b class="kh">{lab[i][0]} {lab[i][1]}</b>{c}', cls=f'kcard k{i}') for i, c in enumerate(cards)) + '</div>'
    if tail: body += ST(len(cards) + 1, '<b class="kt">בחלק הזה</b>' + ''.join(f'<span><i>רמה {k}</i>{TX(t)}</span>' for k, t in tail), cls='ktail')
    S(sid, title, h, body, kick=f'חלק {n} · הסבר קצר לפני התרגול', cls='pfs')


